package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.common.exception.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseP5Test extends PhaseP4Fixtures {
 @Autowired ClinicIntegration integration;@Autowired com.greenocean.backend.identity.AccessPolicy access;
 @BeforeEach void purposeRoles(){for(var a:List.of(issuer,reviewer,other)){role(a.id(),"CLINIC_OPERATIONS");role(a.id(),"CLINIC_PRIVACY_OPERATOR");db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP,reauthenticated_at=CURRENT_TIMESTAMP WHERE id=?",a.session());}}
 UUID recommendation(){delivered();return integration.recommend(author.id(),author.session(),new ClinicIntegration.Recommendation(appointment,null,0,"Synthetic voluntary follow-up recommendation",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(86400)));}
 ClinicCommerce.Booking replacement(){UUID slot=scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"TEXT",0,"Asia/Tehran",true));commerce.offer(author.id(),slot,policy,false);long rev=db.queryForObject("SELECT revision FROM professional_availability_slots WHERE id=?",Long.class,slot);return new ClinicCommerce.Booking(slot,UUID.randomUUID(),rev,policy,0,true);}
 @Test void followupIsEncryptedVersionedAndNeverCreatesAppointmentsOrMessaging(){UUID id=recommendation();long before=db.queryForObject("SELECT count(*) FROM consultation_requests",Long.class);assertThat(integration.followups(learner.id(),learner.session()).toString()).contains("Synthetic voluntary");byte[] cipher=db.queryForObject("SELECT body_cipher FROM clinic_followup_versions WHERE followup_id=?",byte[].class,id);assertThat(new String(cipher)).doesNotContain("voluntary");integration.choose(learner.id(),learner.session(),id,1,"ACCEPT",null);assertThat(db.queryForObject("SELECT count(*) FROM consultation_requests",Long.class)).isEqualTo(before);assertThatThrownBy(()->care.message(learner.id(),learner.session(),db.queryForObject("SELECT e.id FROM clinic_encounters e JOIN clinic_care_relationships r ON r.id=e.relationship_id WHERE r.appointment_id=?",UUID.class,appointment),UUID.randomUUID(),"No indefinite care message")).isInstanceOf(RuntimeException.class);}
 @Test void onlyAssignedProfessionalCanAuthorAndOnlyPatientChooses(){UUID id=recommendation();assertThatThrownBy(()->integration.choose(author.id(),author.session(),id,1,"ACCEPT",null)).isInstanceOf(NotFoundException.class);assertThatThrownBy(()->integration.recommend(learner.id(),learner.session(),new ClinicIntegration.Recommendation(appointment,null,0,"Unauthorized plan",Instant.now().plusSeconds(100),Instant.now().plusSeconds(1000)))).isInstanceOf(ForbiddenException.class);}
 @Test void newRecommendationRevisionNeedsFreshPatientChoice(){UUID id=recommendation();integration.choose(learner.id(),learner.session(),id,1,"ACCEPT",null);integration.recommend(author.id(),author.session(),new ClinicIntegration.Recommendation(appointment,id,1,"Synthetic changed recommendation",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(86400)));assertThat(integration.followups(learner.id(),learner.session()).toString()).contains("choice=null");assertThatThrownBy(()->integration.choose(learner.id(),learner.session(),id,1,"ACCEPT",null)).isInstanceOf(ConflictException.class);}
 @Test void withdrawalIsIndependentAndConsentWithdrawalBlocksAcceptance(){UUID id=recommendation();var n=care.notices(learner.id(),learner.session(),appointment,"en").getFirst();care.consent(learner.id(),learner.session(),appointment,(UUID)n.get("id"),UUID.randomUUID(),"WITHDRAW");assertThatThrownBy(()->integration.choose(learner.id(),learner.session(),id,1,"ACCEPT",null)).isInstanceOf(ConflictException.class);integration.choose(learner.id(),learner.session(),id,1,"WITHDRAW",null);}
 @Test void replacementIsExplicitAtomicAndKeepsOldFinancialSnapshot(){var booking=replacement();var result=integration.reschedule(learner.id(),learner.session(),appointment,1,booking);assertThat(result.get("id")).isNotEqualTo(appointment);assertThat(commerce.appointment(learner.id(),appointment)).containsEntry("status","CANCELLED_BY_PATIENT");assertThat(integration.reschedule(learner.id(),learner.session(),appointment,1,booking).get("id")).isEqualTo(result.get("id"));assertThat(db.queryForObject("SELECT count(*) FROM clinic_booking_changes",Long.class)).isEqualTo(1L);}
 @Test void anotherPatientCannotReplaceTheAppointment(){var b=replacement();assertThatThrownBy(()->integration.reschedule(other.id(),other.session(),appointment,1,b)).isInstanceOf(NotFoundException.class);assertThat(commerce.appointment(learner.id(),appointment)).containsEntry("status","CONFIRMED");}
 @Test void subscriptionCannotBeBoughtTwiceWithDifferentKeys(){UUID plan=commerce.plan(issuer.id(),"p5-"+UUID.randomUUID(),List.of("ADMIN_REPORTS"),0,7);commerce.subscribe(author.id(),plan,UUID.randomUUID(),true);assertThatThrownBy(()->commerce.subscribe(author.id(),plan,UUID.randomUUID(),true)).isInstanceOf(ConflictException.class);assertThat(commerce.subscriptions(author.id()).toString()).contains("ACTIVE_NO_AUTO_RENEWAL");}
 @Test void rightsAreSubjectScopedRetriedAndNeverSilentlyEraseClinicalData(){UUID retry=UUID.randomUUID(),id=integration.rights(learner.id(),learner.session(),appointment,"CLINICAL_NOTES","ERASURE",retry);assertThat(integration.rights(learner.id(),learner.session(),appointment,"CLINICAL_NOTES","ERASURE",retry)).isEqualTo(id);assertThatThrownBy(()->integration.rights(other.id(),other.session(),appointment,"FINANCE","EXPORT",UUID.randomUUID())).isInstanceOf(NotFoundException.class);assertThat(integration.ownRights(learner.id(),learner.session()).toString()).contains("RECEIVED");assertThat(db.queryForObject("SELECT count(*) FROM consultation_requests WHERE id=?",Long.class,appointment)).isEqualTo(1L);}
 @Test void actionEvidenceNeedsIndependentPrivacyReviewAndCurrentHoldStopsIt(){UUID request=integration.rights(learner.id(),learner.session(),appointment,"FINANCE","ERASURE",UUID.randomUUID());assertThatThrownBy(()->integration.reviewRights(issuer.id(),issuer.session(),request,"ACTION_EVIDENCED","SYNTHETIC-ACTION-REFERENCE")).isInstanceOf(ForbiddenException.class);integration.reviewRights(issuer.id(),issuer.session(),request,"UNDER_REVIEW","SYNTHETIC-PRIVACY-REVIEW");UUID hold=integration.hold(issuer.id(),issuer.session(),learner.id(),"FINANCE","SYNTHETIC-DISPUTE-HOLD",Instant.now().plusSeconds(3600));assertThatThrownBy(()->integration.approveHold(issuer.id(),issuer.session(),hold)).isInstanceOf(ForbiddenException.class);integration.approveHold(reviewer.id(),reviewer.session(),hold);assertThatThrownBy(()->integration.reviewRights(reviewer.id(),reviewer.session(),request,"ACTION_EVIDENCED","SYNTHETIC-ACTION-REFERENCE")).isInstanceOf(ConflictException.class);}
 @Test void adminDoesNotReceiveClinicalRightsOrOperationalNarratives(){db.update("DELETE FROM user_roles WHERE user_id=? AND role_id IN(SELECT id FROM roles WHERE name IN('CLINIC_PRIVACY_OPERATOR','CLINIC_OPERATIONS'))",issuer.id());assertThatThrownBy(()->integration.operations(issuer.id(),issuer.session(),"PRIVACY")).isInstanceOf(ForbiddenException.class);String report=integration.operations(issuer.id(),issuer.session(),"BUSINESS").toString();assertThat(report).doesNotContain("body_cipher","patient_id","requester_id","clinical_notes");}
 @Test void operationalViewsExecuteWithoutNarratives(){for(String v:List.of("FINANCE","SAFETY","PRIVACY","BUSINESS"))assertThat(integration.operations(issuer.id(),issuer.session(),v)).isNotNull();assertThat(integration.operations(author.id(),author.session(),"PROFESSIONAL")).isNotNull();}
 @Test void incidentClassificationRequiresTwoIndependentCurrentOperators(){UUID incident=integration.incident(learner.id(),learner.session(),appointment,"CONNECTION"),review=integration.incidentReview(issuer.id(),issuer.session(),incident,"TECHNICAL_FAILURE","SYNTHETIC-PROVIDER-INCIDENT");assertThatThrownBy(()->integration.approveIncident(issuer.id(),issuer.session(),review)).isInstanceOf(ForbiddenException.class);integration.approveIncident(reviewer.id(),reviewer.session(),review);assertThat(db.queryForObject("SELECT count(*) FROM clinic_incident_decisions WHERE review_id=?",Long.class,review)).isEqualTo(1L);}
 @Test void legacyGraceCannotGrantNewClinicalCare(){db.update("UPDATE users SET phase_a_enrolled=FALSE,email_verified=FALSE WHERE id=?",learner.id());assertThatThrownBy(()->access.requireCare(learner.id(),author.id(),"TEXT")).isInstanceOf(ForbiddenException.class);}
 @Test void categoryManifestHasNoInventedRetentionOrAutomaticPurge(){String manifest=integration.manifest(learner.id(),learner.session()).toString();assertThat(manifest).contains("CLINICAL_NOTES","FINANCE","REVIEWS","UNAPPROVED","automatic purge disabled");assertThat(integration.preferences(learner.id(),learner.session()).toString()).contains("optional_enabled=false");integration.preferences(learner.id(),learner.session(),true,"Asia/Tehran",22,8);assertThat(integration.preferences(learner.id(),learner.session()).toString()).contains("Asia/Tehran");}

 @Test void reminderIsOptInDeduplicatedAndWithdrawalStopsDelivery(){UUID id=recommendation();integration.preferences(learner.id(),learner.session(),true,"UTC",0,0);db.update("INSERT INTO clinic_followup_choices(followup_id,revision,patient_id,choice,remind_at) VALUES(?,1,?,'ACCEPT',CURRENT_TIMESTAMP-INTERVAL '1 minute')",id,learner.id());assertThat(integration.reminders(issuer.id(),issuer.session())).isZero();int hour=Instant.now().atZone(ZoneOffset.UTC).getHour();integration.preferences(learner.id(),learner.session(),true,"UTC",(hour+1)%24,(hour+2)%24);assertThat(integration.reminders(issuer.id(),issuer.session())).isEqualTo(1);assertThat(integration.reminders(issuer.id(),issuer.session())).isZero();integration.choose(learner.id(),learner.session(),id,1,"WITHDRAW",null);assertThat(integration.reminders(issuer.id(),issuer.session())).isZero();}
 UUID pastConfirmed(){commerce.change(learner.id(),appointment,new ClinicCommerce.Change(1,"CANCEL","Synthetic fixture replacement"));UUID slot=db.queryForObject("INSERT INTO professional_availability_slots(id,professional_user_id,starts_at,ends_at,consultation_mode,status,governed) VALUES(uuidv7(),?,CURRENT_TIMESTAMP-INTERVAL '20 minutes',CURRENT_TIMESTAMP+INTERVAL '10 minutes','TEXT','BOOKED',TRUE) RETURNING id",UUID.class,author.id());return db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,availability_slot_id,scheduled_at,ends_at,consultation_mode,status,clinic_governed,booking_key,price_units,commission_units,provider_fee_units,currency,policy_id,terms_snapshot,profession_snapshot,confirmed_at) SELECT ?,?,id,starts_at,ends_at,'TEXT','CONFIRMED',TRUE,uuidv7(),0,0,0,'IRR',?,'SYNTHETIC initial past appointment with no service proof','PSYCHOLOGIST',CURRENT_TIMESTAMP FROM professional_availability_slots WHERE id=? RETURNING id",UUID.class,learner.id(),author.id(),policy,slot);}
 @Test void checkboxCannotEstablishNoShowButIndependentEvidenceCan(){UUID a=pastConfirmed();assertThatThrownBy(()->commerce.noShow(issuer.id(),a,"SYNTHETIC-FINANCE-CASE",true)).isInstanceOf(ConflictException.class);db.update("INSERT INTO clinic_readiness_evidence(appointment_id,actor_id,session_id,observed_at) VALUES(?,?,?,CURRENT_TIMESTAMP-INTERVAL '19 minutes')",a,learner.id(),learner.session());UUID i=integration.incident(learner.id(),learner.session(),a,"ATTENDANCE"),r=integration.incidentReview(reviewer.id(),reviewer.session(),i,"NO_OUTAGE","SYNTHETIC-INDEPENDENT-MONITORING");integration.approveIncident(other.id(),other.session(),r);commerce.noShow(issuer.id(),a,"SYNTHETIC-FINANCE-CASE",true);assertThat(commerce.appointment(learner.id(),a)).containsEntry("status","PROFESSIONAL_NO_SHOW");}
 @Test void contradictoryOutageEvidencePreventsProfessionalBlame(){UUID a=pastConfirmed();db.update("INSERT INTO clinic_readiness_evidence(appointment_id,actor_id,session_id,observed_at) VALUES(?,?,?,CURRENT_TIMESTAMP-INTERVAL '19 minutes')",a,learner.id(),learner.session());UUID i=integration.incident(learner.id(),learner.session(),a,"ATTENDANCE"),r=integration.incidentReview(reviewer.id(),reviewer.session(),i,"NO_OUTAGE","SYNTHETIC-INDEPENDENT-MONITORING");integration.approveIncident(other.id(),other.session(),r);integration.incidentReview(other.id(),other.session(),i,"TECHNICAL_FAILURE","SYNTHETIC-PROVIDER-OUTAGE");assertThatThrownBy(()->commerce.noShow(issuer.id(),a,"SYNTHETIC-FINANCE-CASE",true)).isInstanceOf(ConflictException.class);}

 @Autowired com.greenocean.backend.messaging.service.MessagingService messaging;
 @Test void genericProfessionalMessagingCannotBypassBoundedCare(){assertThatThrownBy(()->messaging.startProfessionalConversation(author.id(),learner.id())).isInstanceOf(ForbiddenException.class);}
 @Test void repeatedServerReadinessDoesNotFloodNotices(){for(int i=0;i<3;i++)db.update("INSERT INTO clinic_readiness_evidence(appointment_id,actor_id,session_id) VALUES(?,?,?)",appointment,learner.id(),learner.session());assertThat(db.queryForObject("SELECT count(*) FROM clinic_notice_deliveries WHERE user_id=? AND dedup_key=?",Long.class,learner.id(),"readiness:"+appointment+":"+learner.id())).isEqualTo(1L);}

 @Test void audioOnlyScopeCanListActualAudioOffersWithoutTextAuthorization(){db.update("DELETE FROM professional_scope_authorizations WHERE application_id IN(SELECT id FROM professional_verifications WHERE professional_user_id=?) AND mode='TEXT'",author.id());UUID slot=scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"AUDIO",0,"Asia/Tehran",true));commerce.offer(author.id(),slot,policy,false);assertThat(commerce.offers(learner.id(),author.id()).toString()).contains("AUDIO");}

 @Test void authenticatedProfessionalEncounterEntryPreventsNoShowClassification(){appointment=pastConfirmed();enter();assertThatThrownBy(()->commerce.noShow(issuer.id(),appointment,"SYNTHETIC-FINANCE-CASE",true)).isInstanceOf(ConflictException.class).hasMessageContaining("Attendance");}
}
